/**
 * Igualdade estrutural para dados "JSON-like" mais Date.
 *
 * deepEqual(a, b):
 *   - valores primitivos seguem a semântica de Object.is (NaN é igual a NaN;
 *     +0 e -0 são diferentes);
 *   - objetos só podem ser iguais se tiverem o mesmo protótipo;
 *   - Date: iguais se getTime() for igual pela mesma regra dos primitivos;
 *   - arrays: mesmo comprimento e elementos iguais, na ordem;
 *   - demais objetos: mesmo conjunto de chaves próprias enumeráveis (a ordem
 *     não importa; chave ausente é diferente de chave com valor undefined) e
 *     valores iguais chave a chave;
 *   - funções e símbolos só são iguais a si mesmos.
 * Estruturas cíclicas não são suportadas.
 */
export function deepEqual(a, b) {
  if (Object.is(a, b)) return true;
  if (typeof a !== 'object' || typeof b !== 'object' || a === null || b === null) {
    // Primitivos (ou funções/símbolos) diferentes por Object.is não são iguais
    return false;
  }
  if (Object.getPrototypeOf(a) !== Object.getPrototypeOf(b)) return false;

  if (a instanceof Date) return Object.is(a.getTime(), b.getTime());

  if (Array.isArray(a)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  }

  const keysA = Object.keys(a);
  const keysB = Object.keys(b);
  if (keysA.length !== keysB.length) return false;
  for (const key of keysA) {
    if (!Object.hasOwn(b, key)) return false;
    if (!deepEqual(a[key], b[key])) return false;
  }
  return true;
}

/**
 * Índice do primeiro elemento de `list` estruturalmente igual a `value`, ou -1.
 */
export function indexOfDeep(list, value) {
  for (let i = 0; i < list.length; i++) {
    if (deepEqual(list[i], value)) return i;
  }
  return -1;
}

/**
 * Remove duplicatas estruturais, mantendo a primeira ocorrência de cada valor.
 */
export function uniqueDeep(list) {
  const out = [];
  for (const item of list) {
    if (indexOfDeep(out, item) === -1) out.push(item);
  }
  return out;
}

